def update_reservation_passengers(reservation_id: str, passengers: list):
    """
    Update the passenger information (names / dates of birth) of a reservation.

    You do NOT need to ask the user for a date of birth that is already on the
    reservation, and you do NOT need to re-send passengers whose details are not
    changing:
      - Each passenger object is {"first_name": "Mei", "last_name": "Garcia",
        "dob": "1989-12-13"} where dob is 'YYYY-MM-DD'.
      - If you leave a passenger's dob out, it is filled in from the matching
        passenger already on the reservation (matched by name, then by position),
        so an unchanged birth date never has to be re-typed or asked for.
      - The passenger COUNT cannot change. If you send only the passenger(s) whose
        name is changing, the others already on the reservation are kept unchanged
        automatically, so the final count still matches.

    Args:
        reservation_id: The reservation ID, such as 'ZFA04Y'.
        passengers: A list of passenger objects, each {"first_name": "Mei", "last_name": "Garcia", "dob": "1989-12-13"}.

    Returns:
        The updated reservation.

    Raises:
        ValueError: If the reservation is not found.
        ValueError: If the number of passengers does not match.
    """
    def _as_dict(x):
        if isinstance(x, dict):
            return x
        if hasattr(x, "model_dump"):
            try:
                return x.model_dump()
            except Exception:
                return None
        return None

    def _clean(p):
        return {
            "first_name": p.get("first_name"),
            "last_name": p.get("last_name"),
            "dob": p.get("dob"),
        }

    def _alias_dob(p):
        q = dict(p)
        if not q.get("dob"):
            for alt in ("date_of_birth", "dateOfBirth", "birth_date", "birthday"):
                if q.get(alt):
                    q["dob"] = q[alt]
                    break
        return q

    # Read the existing passengers so a missing dob can be backfilled and a
    # partial (only-the-changed-passenger) update can be completed without
    # changing the passenger count.
    existing = []
    res = _as_dict(env_get_reservation_details(reservation_id=reservation_id))
    if res:
        for p in (res.get("passengers") or []):
            p = _as_dict(p) or (p if isinstance(p, dict) else {})
            if isinstance(p, dict):
                existing.append(p)

    supplied = [_alias_dob(p) for p in passengers if isinstance(p, dict)]

    def _name(p):
        return (str(p.get("first_name", "")).strip().lower(),
                str(p.get("last_name", "")).strip().lower())

    # Bounded partial-list merge: only when the reservation is known, fewer
    # passengers were supplied than exist, and every supplied passenger maps to a
    # DISTINCT existing passenger by first name. Otherwise fall through untouched.
    result_list = None
    if existing and 0 < len(supplied) < len(existing) and len(supplied) == len([p for p in passengers if isinstance(p, dict)]):
        merged = [dict(e) for e in existing]
        used = set()
        ok = True
        for s in supplied:
            sf = str(s.get("first_name", "")).strip().lower()
            matches = [i for i, e in enumerate(existing)
                       if i not in used and str(e.get("first_name", "")).strip().lower() == sf]
            if len(matches) != 1:
                ok = False
                break
            idx = matches[0]
            used.add(idx)
            m = dict(existing[idx])
            if s.get("first_name"):
                m["first_name"] = s["first_name"]
            if s.get("last_name"):
                m["last_name"] = s["last_name"]
            if s.get("dob"):
                m["dob"] = s["dob"]
            merged[idx] = m
        if ok:
            result_list = [_clean(m) for m in merged]

    if result_list is None:
        # Same-count path: backfill each missing dob from the matching existing
        # passenger (by full name, then first name, then position).
        name_dob = {}
        for e in existing:
            if e.get("dob"):
                name_dob[_name(e)] = e["dob"]
                fn = str(e.get("first_name", "")).strip().lower()
                name_dob.setdefault((fn, ""), e["dob"])
        out = []
        raw = [p for p in passengers]
        for i, p in enumerate(raw):
            if not isinstance(p, dict):
                out.append(p)
                continue
            q = _alias_dob(p)
            if not q.get("dob"):
                fn = str(q.get("first_name", "")).strip().lower()
                cand = name_dob.get(_name(q)) or name_dob.get((fn, ""))
                if not cand and i < len(existing):
                    cand = existing[i].get("dob")
                if cand:
                    q["dob"] = cand
            out.append(_clean(q))
        result_list = out

    return env_update_reservation_passengers(reservation_id=reservation_id, passengers=result_list)
